async function sendWelcomeEmail(params) {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) {
    logger2.warn("RESEND_API_KEY not set \u2014 skipping welcome email");
    return;
  }
  try {
    const resend2 = new Resend(apiKey);
    await resend2.emails.send({
      from: "QuoteAI <no-reply@quoteai.ca>",
      to: [params.toEmail],
      subject: "Welcome to QuoteAI \u2014 your account is ready \u{1F389}",
      html: buildWelcomeEmail(params.toName)
    });
    logger2.info({ to: params.toEmail }, "Welcome email sent");
  } catch (err) {
    logger2.error({ err }, "Failed to send welcome email (non-fatal)");
  }
}
