    if (body.titoloPreventivoRiga1 !== void 0) updates.titoloPreventivoRiga1 = body.titoloPreventivoRiga1 ?? null;
    if (body.titoloPreventivoRiga2 !== void 0) updates.titoloPreventivoRiga2 = body.titoloPreventivoRiga2 ?? null;
    if (body.note !== void 0) updates.note = body.note;
    if (body.status !== void 0) updates.status = body.status;
    if (body.subtotale !== void 0) updates.subtotale = String(body.subtotale);
    if (body.ivaPercentuale !== void 0) updates.ivaPercentuale = String(body.ivaPercentuale);
    if (body.ivaValore !== void 0) updates.ivaValore = String(body.ivaValore);
