function parseHtmlSeo(html2) {
  const titleMatch = html2.match(/<title>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : "";
  const descMatch = html2.match(/<meta\s+name=["']description["']\s+content=["']([\s\S]*?)["']/i) || html2.match(/<meta\s+content=["']([\s\S]*?)["']\s+name=["']description["']/i);
  const description = descMatch ? descMatch[1].trim() : "";
  const h1Matches = [...html2.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)];
  const h1 = h1Matches.length > 0 ? h1Matches[0][1].replace(/<[^>]*>/g, "").trim() : "";
  const imgTags = [...html2.matchAll(/<img\s+([\s\S]*?)>/gi)];
  let missingAlt = 0;
  for (const tag2 of imgTags) {
    const attrs = tag2[1];
    if (!/alt=["']/i.test(attrs) || /alt=["']\s*["']/i.test(attrs)) {
      missingAlt++;
    }
  }
  const ogTitle = (html2.match(/<meta\s+property=["']og:title["']\s+content=["']([\s\S]*?)["']/i) || [])[1] || "";
  const ogImage = (html2.match(/<meta\s+property=["']og:image["']\s+content=["']([\s\S]*?)["']/i) || [])[1] || "";
  let score = 100;
  const issues = [];
  if (!title) {
    score -= 20;
    issues.push("Missing <title> tag");
  } else if (title.length < 30 || title.length > 65) {
    score -= 10;
    issues.push(`Suboptimal title length (${title.length} characters). Recommended 30-65.`);
  }
  if (!description) {
    score -= 20;
    issues.push("Missing meta description");
  } else if (description.length < 120 || description.length > 160) {
    score -= 10;
    issues.push(`Suboptimal description length (${description.length} characters). Recommended 120-160.`);
  }
  if (h1Matches.length === 0) {
    score -= 15;
    issues.push("Missing <h1> tag");
  } else if (h1Matches.length > 1) {
    score -= 10;
    issues.push(`Multiple <h1> tags detected (${h1Matches.length}). Only one is recommended.`);
  }
  if (missingAlt > 0) {
    score -= Math.min(15, missingAlt * 3);
    issues.push(`${missingAlt} images missing an 'alt' attribute`);
  }
  if (!ogTitle || !ogImage) {
    score -= 5;
    issues.push("Incomplete or missing OpenGraph tags for social media");
  }
  return {
    title,
    description,
    h1,
    score: Math.max(0, score),
    issues
  };
}
