function signGoogleJwt(clientEmail, privateKey, keyId) {
  const payload = {
    iss: clientEmail,
    scope: "https://www.googleapis.com/auth/webmasters.readonly",
    aud: "https://oauth2.googleapis.com/token",
    exp: Math.floor(Date.now() / 1e3) + 3600,
    iat: Math.floor(Date.now() / 1e3)
  };
  const header = {
    alg: "RS256",
    typ: "JWT",
    kid: keyId
  };
  const base64Header = Buffer.from(JSON.stringify(header)).toString("base64url");
  const base64Payload = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const signatureInput = `${base64Header}.${base64Payload}`;
  const signer = crypto4.createSign("RSA-SHA256");
  signer.update(signatureInput);
  const signature = signer.sign(privateKey, "base64url");
  return `${signatureInput}.${signature}`;
}
async function getGoogleAccessToken(serviceAccountJson) {
  const sa = JSON.parse(serviceAccountJson);
  const jwt2 = signGoogleJwt(sa.client_email, sa.private_key, sa.private_key_id);
  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded"
    },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: jwt2
    })
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Google OAuth error: ${res.status} - ${errText}`);
  }
  const data = await res.json();
  return data.access_token;
}
